export const DropdownVisibility = {
  Opening: 'Opening', // Animating open
  Open: 'Open',       // Fully open
  Closing: 'Closing', // Animating close
  Closed: 'Closed',   // Fully closed
} as const;
type DropdownVisibilityValues<T> = T[keyof T];
export type DropdownVisibilityType = DropdownVisibilityValues<typeof DropdownVisibility>;

export interface Placeholder {
  text: string;
  color?: string;
  fontSize?: number;
  fontWeight?: number;
  fontFamily?: string;
}

export interface ArrowComponentProps {
  color: string;
  borderColor?: string;
  visibility: DropdownVisibilityType;
  animationDuration: number;
}

export interface ScrollData {
  visibleHeight: number;
  totalHeight: number;
  scrollPosition: number;
  maxScroll: number;
  client: {
    height: number | undefined;
    left: number | undefined;
    top: number | undefined;
    width: number | undefined;
  };
  offset: {
    height: number | undefined;
    left: number | undefined;
    top: number | undefined;
    width: number | undefined;
  };
  scroll: {
    height: number | undefined;
    left: number | undefined;
    top: number | undefined;
    width: number | undefined;
  };
}

export interface Border {
  color?: string;
  width: number;
  style?: string;
  radius?: string | number;
}

interface CommonStyle {
  border?: Border | string;
  backgroundColor?: string;
  color?: string;
  fontSize?: number;
  fontWeight?: number | "normal" | "bold" | "bolder" | "lighter";
  fontFamily?: string;
  cursor?: string;
}

export interface ComponentStyle extends CommonStyle {
  arrowColor?: string;
  arrowBorderColor?: string;
}

export interface DropdownStyle extends CommonStyle {
  animationDuration?: number;
  dropdownDirection?: 'up' | 'down';
  hoverColor?: string;
  maxDropHeight?: number;
  selectedColor?: string;
  selectedBackgroundColor?: string;
  separatorColor?: string;
  separatorThickness?: number;
  separatorStyle?: 'solid' | 'dotted' | 'dashed';
}

export interface Size {
  width: number;
  height: number;
  top: number;
  left: number;
}

export const DEFAULT_ANIMATION_DURATION = 300;
export const DEFAULT_MAX_DROP_HEIGHT = 225;
export const DEFAULT_DROPDOWN_BORDER = { color: 'transparent', width: 0, style: 'none', radius: 0 };
export const DEFAULT_PADDING = 10;

import { Border, ScrollData } from "./types";

export function toBorder(border: Border | string | undefined | null): Border {
  if (!border) {
    return { color: 'transparent', width: 0, style: 'none', radius: 0 };
  }
  if (typeof border === 'string') {
    const [width, style, color] = border.split(' ');
    return {
      width: parseInt(width) || 0,
      style: style || 'none',
      color: color || 'transparent',
      radius: 0,
    };
  }
  return border;
}

export function toScrollData(event: EventTarget | null): ScrollData | null {
  if (!event) return null;

  const el = event as HTMLElement;

  const visibleHeight = el.clientHeight || 0;
  const totalHeight = el.scrollHeight || 0;
  const scrollPosition = el.scrollTop || 0;
  const maxScroll = totalHeight - visibleHeight;

  return {
    visibleHeight,
    totalHeight,
    scrollPosition,
    maxScroll,
    client: {
      height: el.clientHeight,
      left: el.clientLeft,
      top: el.clientTop,
      width: el.clientWidth,
    },
    offset: {
      height: el.offsetHeight,
      left: el.offsetLeft,
      top: el.offsetTop,
      width: el.offsetWidth,
    },
    scroll: {
      height: el.scrollHeight,
      left: el.scrollLeft,
      top: el.scrollTop,
      width: el.scrollWidth,
    },
  };
}

import { toBorder } from "./helpers";
import { Border, ComponentStyle } from "./types";

type DropdownStyleInput = {
  name: 'dropdown';
  style: {
    width: number | string;
    componentStyle?: ComponentStyle;
    border: Border | string;
  };
} | {
  name: 'dropdown-header';
  style: {
    componentStyle: ComponentStyle;
    padding: number;
  };
};

export interface DropdownStyleResult {
  border: string;
  padding: string;
  width: string;
  fontFamily: string;
  fontSize: string;
  fontWeight: string;
  backgroundColor: string;
}

export interface DropdownHeaderStyleResult {
  backgroundColor: string;
  padding: string;
  color: string;
}

export function getStyles(dStyle: DropdownStyleInput): DropdownStyleResult | DropdownHeaderStyleResult {
  switch (dStyle.name) {
    case 'dropdown':
      {
        const { width, componentStyle, border } = dStyle.style;
        const borderObject = toBorder(border);
        const borderStyle = `${borderObject.width}px ${borderObject.style} ${borderObject.color}`;
        return {
          width: `${typeof width === 'number' ? `${width}px` : width}`,
          fontFamily: `${componentStyle?.fontFamily || 'Arial'}`,
          fontSize: `${componentStyle?.fontSize || 16}px`,
          fontWeight: `${componentStyle?.fontWeight || 400}`,
          backgroundColor: `${componentStyle?.backgroundColor || 'transparent'}`,
          padding: `${borderObject.width}px`,
          border: borderStyle,
        } as DropdownStyleResult;
      }
    case 'dropdown-header':
      {
        const { componentStyle, padding } = dStyle.style;
        return {
          backgroundColor: `${componentStyle.backgroundColor}`,
          padding: `${padding}px`,
          color: `${componentStyle.color || 'black'}`,
        } as DropdownHeaderStyleResult ;
      }
  };
}

import React from 'react';
import { DropdownVisibility, ArrowComponentProps } from '../types';

export function DefaultArrow({ visibility, color, borderColor, animationDuration }: ArrowComponentProps) {
  return (
    <svg
      style={{
        transition: `transform ${animationDuration / 1000}s ease`,
        transform: visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening ? 'rotate(180deg)' : 'rotate(0deg)',
      }}
      width="30"
      height="30"
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 100 100"
    >
      <circle cx="50" cy="50" r="45" stroke={borderColor ? borderColor : color} strokeWidth="1" fill="none" />
      <text x="50" y="60" fontSize="60" textAnchor="middle" alignmentBaseline="middle" fill={color}>
        ▼
      </text>
    </svg>
  );
}

import React from 'react';
import { DEFAULT_ANIMATION_DURATION, DEFAULT_DROPDOWN_BORDER, DEFAULT_PADDING } from '../constants';
import { DefaultArrow } from '../DefaultArrow/DefaultArrow';
import { DropdownList } from '../DropdownList/DropdownList';
import { toScrollData } from '../helpers';
import { Border, ComponentStyle, DropdownStyle, ArrowComponentProps, Placeholder } from '../types';
import { useDropdownList } from '../DropdownList/useDropdownList';
import { DropdownHeaderStyleResult, DropdownStyleResult, getStyles } from '../useStyles';

import './Dropdown.css';

interface DropdownProps<T> {
  items: T[];
  ArrowComponent?: React.FC<ArrowComponentProps>;
  renderItem: (item: T | null, index: number, isSelected: boolean) => React.ReactNode;
  width?: number | string;
  padding?: number;
  onSelect?: (item: T | null, index: number) => void;
  border?: Border | string;
  placeholder?: Placeholder;
  componentStyle?: ComponentStyle;
  dropdownStyle?: DropdownStyle;
  disabled?: boolean;
  allowNoSelection?: boolean;
}

export function Dropdown<T>({
  ArrowComponent = DefaultArrow,
  items,
  renderItem,
  onSelect,
  width = 'auto',
  padding = DEFAULT_PADDING,
  placeholder,
  componentStyle,
  dropdownStyle,
  border = DEFAULT_DROPDOWN_BORDER,
  disabled = false,
  allowNoSelection = false,
}: DropdownProps<T>) {
  const {
    visibility,
    selectedIndex,
    selectedItem,
    effectiveMaxHeight,
    effectiveDirection,
    scrollData,
    itemRefs,
    dropdownRef,
    listRef,
    toggleDropdown,
    onItemClick,
    onKeyDown,
    onWheel,
  } = useDropdownList<T>({
    allowNoSelection,
    disabled,
    animationDuration: dropdownStyle?.animationDuration,
    maxDropHeight: dropdownStyle?.maxDropHeight,
    dropdownDirection: dropdownStyle?.dropdownDirection,
    items,
    onSelect,
  });

  const { border: borderStyle, ...dropDownStyle } = getStyles({
    name: 'dropdown',
    style: {
      width,
      componentStyle,
      border,
    },
  }) as DropdownStyleResult;

  const { padding: headerPadding, ...headerStyle } = getStyles({
    name: 'dropdown-header',
    style: {
      componentStyle: componentStyle || { backgroundColor: 'transparent', color: 'black' },
      padding,
    },
  }) as DropdownHeaderStyleResult;

  const animationDuration = dropdownStyle?.animationDuration || DEFAULT_ANIMATION_DURATION;

  const itemStyle: React.CSSProperties = {
    color: dropdownStyle?.color || 'black',
    padding: `${padding}px`,
    cursor: 'pointer',
    ...(dropdownStyle?.separatorColor ? {
      borderBottom: `${dropdownStyle?.separatorThickness || 1}px ${dropdownStyle?.separatorStyle || 'solid'} ${dropdownStyle?.separatorColor}`,
    } : {}),
  };

  const itemHoverColor = dropdownStyle?.hoverColor || 'transparent';

  return (
    <div className="dropdown" ref={dropdownRef} style={dropDownStyle}>
      <div
        className="dropdown-header"
        tabIndex={disabled ? -1 : 0}
        onClick={toggleDropdown}
        onKeyDown={onKeyDown}
        style={{
          ...headerStyle,
          padding,
        }}
        onWheel={onWheel}
      >
        <span
          style={{
            color: selectedItem ? componentStyle?.color : placeholder?.color || 'black',
            fontSize: selectedItem ? componentStyle?.fontSize : placeholder?.fontSize || 16,
            fontWeight: selectedItem ? componentStyle?.fontWeight : placeholder?.fontWeight || 900,
            fontFamily: selectedItem ? componentStyle?.fontFamily : placeholder?.fontFamily || 'Times New Roman',
            paddingRight: `${padding}px`,
          }}
        >
          {selectedItem ? renderItem(selectedItem, selectedIndex, false) : placeholder?.text}
        </span>
        <ArrowComponent
          color={componentStyle?.arrowColor || 'black'}
          borderColor={componentStyle?.arrowBorderColor || 'black'}
          visibility={visibility}
          animationDuration={animationDuration}
        />
      </div>
      <DropdownList
        renderItem={renderItem}
        disabled={disabled}
        items={items}
        selectedItem={selectedItem}
        selectedIndex={selectedIndex}
        allowNoSelection={allowNoSelection}
        onItemClick={onItemClick}
        visibility={visibility}
        dropdownStyle={dropdownStyle}
        effectiveMaxHeight={effectiveMaxHeight}
        effectiveDirection={effectiveDirection}
        padding={padding}
        borderStyle={borderStyle}
        listRef={listRef}
        itemRefs={itemRefs}
        scrollData={scrollData}
        itemStyle={itemStyle}
        itemHoverColor={itemHoverColor}
        onScroll={(e) => scrollData.current = toScrollData(e.nativeEvent.target)}
      />
    </div>
  );
}

.dropdown {
  position: relative;
  border: none;
  cursor: default;
}

.dropdown-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
}

.dropdown-header:focus {
  outline: none;
}

.dropdown-header:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 2px #0078d4, inset 0 0 0 3px #fff;
}

import React, { MutableRefObject, ReactNode, RefObject, UIEvent, useEffect, useState } from 'react';
import { DEFAULT_ANIMATION_DURATION, DEFAULT_MAX_DROP_HEIGHT } from '../constants';
import { DropdownStyle, DropdownVisibility, DropdownVisibilityType, ScrollData } from '../types';

import "./DropdownList.css";

interface DropdownListProps<T> {
  items: T[];
  selectedItem: T | null;
  selectedIndex: number;
  allowNoSelection?: boolean;
  onItemClick: (item: T | null, index: number) => void;
  visibility: DropdownVisibilityType;
  dropdownStyle?: DropdownStyle;
  effectiveMaxHeight?: number;
  effectiveDirection?: 'up' | 'down';
  padding?: number;
  borderStyle?: string;
  listRef: RefObject<HTMLUListElement>;
  itemRefs: RefObject<(HTMLLIElement | null)[]>;
  scrollData: MutableRefObject<ScrollData | null>;
  renderItem: (item: T | null, index: number, isSelected: boolean) => ReactNode;
  disabled?: boolean;
  onScroll?: (e: UIEvent<HTMLUListElement>) => void;
  itemStyle?: React.CSSProperties;
  itemHoverColor?: string;
}

export function DropdownList<T>({
  items,
  selectedItem,
  selectedIndex,
  allowNoSelection = false,
  onItemClick,
  visibility,
  dropdownStyle,
  effectiveMaxHeight,
  effectiveDirection,
  padding = 0,
  borderStyle = 'none',
  listRef,
  itemRefs,
  scrollData,
  renderItem,
  disabled = false,
  onScroll,
  itemStyle = {},
  itemHoverColor = 'transparent',
}: DropdownListProps<T>) {
  const maxDropHeight = effectiveMaxHeight ?? dropdownStyle?.maxDropHeight ?? DEFAULT_MAX_DROP_HEIGHT;
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

  useEffect(() => {
    if (selectedIndex < 0 || !listRef.current || !itemRefs.current?.[selectedIndex]) return;

    const list = listRef.current;
    const scrollTop = list.scrollTop;
    const clientHeight = list.clientHeight;
    const itemTop = itemRefs.current[selectedIndex].offsetTop;
    const itemHeight = itemRefs.current[selectedIndex].offsetHeight;
    const itemBottom = itemTop + itemHeight;

    // Already fully visible — do nothing
    if (itemTop >= scrollTop && itemBottom <= scrollTop + clientHeight) return;

    // Item is below the viewport — scroll down just enough to show it at the bottom
    if (itemBottom > scrollTop + clientHeight) {
      list.scrollTo({ top: itemBottom - clientHeight, behavior: 'smooth' });
    }
    // Item is above the viewport — scroll up just enough to show it at the top
    else if (itemTop < scrollTop) {
      list.scrollTo({ top: itemTop, behavior: 'smooth' });
    }
  }, [selectedIndex]);

  const animationDuration = dropdownStyle?.animationDuration || DEFAULT_ANIMATION_DURATION;
  const transition = `max-height ${animationDuration / 1000}s ease, opacity ${animationDuration / 1000}s ease`;

  const getItemStyle = (item: T | null, index: number): React.CSSProperties => {
    const isSelected = selectedItem === item;
    const isHovered = hoveredIndex === index;
    return {
      ...itemStyle,
      color: isSelected ? dropdownStyle?.selectedColor : dropdownStyle?.color || 'black',
      backgroundColor: isHovered
        ? itemHoverColor
        : isSelected
          ? dropdownStyle?.selectedBackgroundColor
          : dropdownStyle?.backgroundColor,
    };
  };

  return (
    <ul
      ref={listRef}
      className={`dropdown-list ${(effectiveDirection ?? dropdownStyle?.dropdownDirection) === 'up' ? 'up' : 'down'}`}
      style={{
        border: borderStyle,
        borderTop: 'none',
        maxHeight: visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening ? maxDropHeight : 0,
        opacity: visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening ? 1 : 0,
        backgroundColor: dropdownStyle?.backgroundColor,
        transition,
      }}
      onScroll={onScroll}
    >
      {allowNoSelection && (
        <li
          onClick={() => onItemClick(null, -1)}
          onMouseEnter={() => setHoveredIndex(-1)}
          onMouseLeave={() => setHoveredIndex(null)}
          style={getItemStyle(null, -1)}
        >
          {renderItem(null, -1, false)}
        </li>
      )}
      {items.map((item, index) => (
        <li
          key={index}
          ref={(el) => { if (itemRefs.current) itemRefs.current[index] = el; }}
          onClick={() => !disabled && onItemClick(item, index)}
          onMouseEnter={() => setHoveredIndex(index)}
          onMouseLeave={() => setHoveredIndex(null)}
          style={getItemStyle(item, index)}
        >
          {renderItem(item, index, selectedIndex === index)}
        </li>
      ))}
    </ul>
  );
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { DropdownVisibility, DropdownVisibilityType, ScrollData } from '../types';
import { DEFAULT_MAX_DROP_HEIGHT, DEFAULT_ANIMATION_DURATION } from '../constants';

interface UseDropdownProps<T> {
  items: T[];
  onSelect?: (item: T | null, index: number) => void;
  maxDropHeight?: number;
  animationDuration?: number;
  disabled?: boolean;
  allowNoSelection?: boolean;
  dropdownDirection?: 'up' | 'down';
}

export function useDropdownList<T>({
  items,
  onSelect,
  maxDropHeight = DEFAULT_MAX_DROP_HEIGHT,
  animationDuration = DEFAULT_ANIMATION_DURATION,
  disabled = false,
  allowNoSelection = false,
  dropdownDirection = 'down',
}: UseDropdownProps<T>) {
  const [visibility, setVisibility] = useState<DropdownVisibilityType>(DropdownVisibility.Closed);
  const [selectedIndex, setSelectedIndex] = useState<number>(-1);
  const [selectedItem, setSelectedItem] = useState<T | null>(null);
  const [effectiveMaxHeight, setEffectiveMaxHeight] = useState(maxDropHeight);
  const [effectiveDirection, setEffectiveDirection] = useState(dropdownDirection);
  const scrollData = useRef<ScrollData | null>(null) as React.MutableRefObject<ScrollData | null>;
  const itemRefs = useRef<(HTMLLIElement | null)[]>([]) as React.MutableRefObject<(HTMLLIElement | null)[]>;
  const dropdownRef = useRef<HTMLDivElement>(null) as React.RefObject<HTMLDivElement>;
  const listRef = useRef<HTMLUListElement>(null) as React.RefObject<HTMLUListElement>;
  const animationTimeout = useRef<NodeJS.Timeout>(undefined);
  const closeDropdownRef = useRef<(callback?: () => void) => void>(() => {});

  const computeEffectiveLayout = useCallback(() => {
    if (!dropdownRef.current) return { maxHeight: maxDropHeight, direction: dropdownDirection };
    const rect = dropdownRef.current.getBoundingClientRect();
    const margin = 8;
    const spaceBelow = window.innerHeight - rect.bottom - margin;
    const spaceAbove = rect.top - margin;

    // Auto-flip when the preferred direction can't fit the dropdown and the other side has more room
    let direction = dropdownDirection;
    const preferredSpace = dropdownDirection === 'down' ? spaceBelow : spaceAbove;
    const alternateSpace = dropdownDirection === 'down' ? spaceAbove : spaceBelow;
    if (preferredSpace < maxDropHeight && alternateSpace > preferredSpace) {
      direction = dropdownDirection === 'down' ? 'up' : 'down';
    }

    const available = direction === 'up' ? spaceAbove : spaceBelow;
    return {
      maxHeight: Math.max(50, Math.min(maxDropHeight, available)),
      direction,
    };
  }, [maxDropHeight, dropdownDirection]);

  // Recompute layout when props change while open; only reset when fully closed
  useEffect(() => {
    const isOpen = visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening;
    if (isOpen) {
      const layout = computeEffectiveLayout();
      setEffectiveMaxHeight(layout.maxHeight);
      setEffectiveDirection(layout.direction);
    } else if (visibility === DropdownVisibility.Closed) {
      setEffectiveMaxHeight(maxDropHeight);
      setEffectiveDirection(dropdownDirection);
    }
  }, [maxDropHeight, dropdownDirection, visibility, computeEffectiveLayout]);

  const ensureVisible = (height?: number) => {
    if (selectedIndex < 0 || !listRef.current || !itemRefs.current[selectedIndex]) return;

    const mh = height ?? effectiveMaxHeight;
    const { client, scroll } = scrollData.current || {};

    // Safe numbers
    const scrollTop = scroll?.top || 0;
    const clientHeight = client?.height || 0;

    // The position and height of the selected item
    const selectedItemPosition = itemRefs.current[selectedIndex].offsetTop;
    const selectedItemHeight = itemRefs.current[selectedIndex].offsetHeight;

    // Guard clause to prevent scrolling if the selected item is already visible
    if (selectedItemPosition >= scrollTop && selectedItemPosition + selectedItemHeight <= scrollTop + clientHeight) return;

    // Move the selected item to the top of the dropdown list
    listRef.current.scrollTo({
      top: selectedItemPosition - (Math.floor(mh || 0)) / 2 + selectedItemHeight / 2,
      behavior: 'smooth',
    })
  }

  // Start the closing dropdown animation. The callback is used when the animation is done
  // to delay updating the parent component until the animation is done.
  const closeDropdown = useCallback((callback: () => void = () => { }) => {
    setVisibility(DropdownVisibility.Closing);
    if (animationTimeout.current) clearTimeout(animationTimeout.current);
    animationTimeout.current = setTimeout(() => {
      setVisibility(DropdownVisibility.Closed);
      callback();
    }, animationDuration);
  }, [animationDuration]);

  // Keep the ref in sync so the click-outside handler always uses the latest version
  closeDropdownRef.current = closeDropdown;

  // Start the opening dropdown animation
  const openDropdown = () => {
    if (visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening || disabled) return;
    const layout = computeEffectiveLayout();
    setEffectiveMaxHeight(layout.maxHeight);
    setEffectiveDirection(layout.direction);
    ensureVisible(layout.maxHeight);
    setVisibility(DropdownVisibility.Opening);
    if (animationTimeout.current) clearTimeout(animationTimeout.current);
    animationTimeout.current = setTimeout(() => {
      setVisibility(DropdownVisibility.Open);
    }, animationDuration);
  }

  // Toggle the dropdown visibility
  const toggleDropdown = () => {
    if (visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening) {
      closeDropdown();
    } else {
      openDropdown();
    }
  }

  // Close the dropdown when clicking outside of it
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node | null))
        closeDropdownRef.current();
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Clear animation timeout on unmount
  useEffect(() => {
    return () => {
      if (animationTimeout.current) clearTimeout(animationTimeout.current);
    };
  }, []);

  // Handle item selection and closing the dropdown
  const onItemClick = useCallback(
    (item: T | null, index: number) => {
      setSelectedIndex(index);
      setSelectedItem(item);
      closeDropdown(() => onSelect?.(item, index));
    },
    [onSelect, closeDropdown]
  );

  // Handle keyboard navigation
  const onKeyDown = (event: React.KeyboardEvent) => {
    if (disabled) return;
    const isOpen = visibility === DropdownVisibility.Open || visibility === DropdownVisibility.Opening;

    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        if (isOpen && selectedIndex >= 0) {
          onItemClick(items[selectedIndex], selectedIndex);
        } else {
          toggleDropdown();
        }
        break;
      case 'Escape':
        if (isOpen) {
          event.preventDefault();
          closeDropdown();
        }
        break;
      case 'ArrowDown':
        event.preventDefault();
        if (!isOpen) {
          openDropdown();
        }
        setSelectedIndex((prev) => {
          const next = prev >= items.length - 1 ? prev : prev + 1;
          setSelectedItem(next >= 0 ? items[next] : null);
          return next;
        });
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (!isOpen) {
          openDropdown();
        }
        setSelectedIndex((prev) => {
          const next = prev <= 0 ? (allowNoSelection ? -1 : 0) : prev - 1;
          setSelectedItem(next >= 0 ? items[next] : null);
          return next;
        });
        break;
      case 'PageDown':
        event.preventDefault();
        if (isOpen && listRef.current) {
          listRef.current.scrollBy({ top: listRef.current.clientHeight, behavior: 'smooth' });
        }
        break;
      case 'PageUp':
        event.preventDefault();
        if (isOpen && listRef.current) {
          listRef.current.scrollBy({ top: -listRef.current.clientHeight, behavior: 'smooth' });
        }
        break;
    }
  };

  // Handles the wheel event, adjusting the selected index by +/- 1
  const onWheel = (event: React.WheelEvent) => {
    if (disabled) return;
    const increase = event.deltaY > 0;
    setSelectedIndex((prev) => {
      if (increase) {
        return prev === items.length - 1 ? prev : prev + 1;
      } else {
        return prev <= 0 ? allowNoSelection ? -1 : 0 : prev - 1;
      }
    });
    setSelectedItem((prev) => {
      if (prev === null) return increase ? items[0] : null;
      if (increase) {
        const nextIndex = items.indexOf(prev) + 1;
        return nextIndex === items.length ? prev : items[nextIndex];
      } else {
        const nextIndex = items.indexOf(prev) - 1;
        return nextIndex === -1 ? allowNoSelection ? null : prev : items[nextIndex];
      }
    });
  };

  return {
    visibility,
    selectedIndex,
    selectedItem,
    effectiveMaxHeight,
    effectiveDirection,
    toggleDropdown,
    onItemClick,
    dropdownRef,
    scrollData,
    itemRefs,
    listRef,
    closeDropdown,
    openDropdown,
    ensureVisible,
    onKeyDown,
    onWheel,
  };
}

.dropdown-list {
  position: absolute;
  left: 0%;
  right: 0;
  margin: 0;
  padding: 0;
  border-top: none;
  overflow-y: scroll;
  z-index: 1000;
}

.dropdown-list.up {
  top: auto;
  bottom: 100%;
}

.dropdown-list.down {
  top: 100%;
  bottom: auto;
}
